contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);

        uint beforeBal = address(c).balance;
        uint beforeOwnerBal = c.Owner().balance;
        address beforeOwner = c.Owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Command{value: amount}(address(this), ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBal = address(c).balance;
        address afterOwner = c.Owner(); if (__ESBMC_reverted()) return;

        assert(reverted || (afterBal >= beforeBal && afterOwner == beforeOwner));
    }
}

