pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount > 0);
        uint beforeBal = address(c).balance;
        uint beforeOwnerBal = c.Owner().balance;
        address beforeOwner;
        try c.Owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        bool reverted;
        try c.Command{value: amount}(address(this), "") {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterBal = address(c).balance;
        address afterOwner;
        try c.Owner() returns (address __r) { afterOwner = __r; } catch { return; }
        assertTrue(reverted || (afterBal >= beforeBal && afterOwner == beforeOwner));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
